export function playAsciiReveal(canvas, art, { duration = 1400 } = {}) {
  if (!canvas) return () => {};
  const ctx = canvas.getContext('2d');
  const lines = String(art).replace(/\r/g, '').replace(/^\n+/, '').replace(/\n+$/, '').split('\n');
  let raf = 0;
  let start = 0;
  let running = true;

  function fit() {
    const host = canvas.parentElement;
    if (!host) return;
    const rect = host.getBoundingClientRect();
    canvas.width = Math.max(1, Math.floor(rect.width));
    canvas.height = Math.max(1, Math.floor(rect.height));
    canvas.style.width = rect.width + 'px';
    canvas.style.height = rect.height + 'px';
    ctx.setTransform(1, 0, 0, 1, 0, 0);
  }

  function draw(t) {
    const w = canvas.width;
    const h = canvas.height;
    ctx.clearRect(0, 0, w, h);
    if (!lines.length) return;

    const cols = Math.max(...lines.map((l) => l.length));
    const rows = lines.length;
    const marginCols = 4;
    const marginRows = 4;
    let px = Math.floor(Math.min(
      w / Math.max(10, cols + marginCols),
      h / Math.max(8, rows + marginRows),
    ));
    px = Math.max(7, Math.min(px, 16));

    const ink = getComputedStyle(document.documentElement).getPropertyValue('--ink').trim() || '#55ff55';
    const muted = getComputedStyle(document.documentElement).getPropertyValue('--ink-muted').trim() || '#007700';
    ctx.font = `${px}px "VT323", monospace`;
    ctx.textBaseline = 'top';
    ctx.textAlign = 'left';
    ctx.fillStyle = ink;

    const charW = ctx.measureText('M').width || px;
    const lineH = Math.max(1, Math.round(px * 1.1));
    const blockW = charW * cols;
    const blockH = lineH * rows;
    const left = Math.max(8, Math.round((w - blockW) / 2));
    const top = Math.max(8, Math.round((h - blockH) / 2));
    const revealCols = Math.floor(cols * t);

    for (let r = 0; r < rows; r++) {
      const slice = (lines[r] || '').slice(0, revealCols);
      if (slice) ctx.fillText(slice, left, top + r * lineH);
    }

    ctx.globalAlpha = 0.06;
    ctx.fillStyle = ink;
    for (let y = 0; y < h; y += 3) ctx.fillRect(0, y, w, 1);
    ctx.globalAlpha = 1;

    if (t > 0.98) {
      ctx.globalAlpha = 0.35;
      for (let i = 0; i < 12; i++) {
        ctx.fillStyle = i % 2 ? ink : muted;
        ctx.fillRect(
          left + Math.random() * blockW,
          top + Math.random() * blockH,
          (Math.random() * charW * 6) + charW * 2,
          1,
        );
      }
      ctx.globalAlpha = 1;
    }
  }

  function tick(now) {
    if (!running) return;
    const t = Math.min(1, (now - start) / duration);
    draw(t);
    if (t < 1) raf = requestAnimationFrame(tick);
  }

  function startReveal() {
    cancelAnimationFrame(raf);
    fit();
    start = performance.now();
    raf = requestAnimationFrame(tick);
  }

  const onResize = () => { if (running) startReveal(); };
  raf = requestAnimationFrame(startReveal);
  addEventListener('resize', onResize, { passive: true });

  return () => {
    running = false;
    cancelAnimationFrame(raf);
    removeEventListener('resize', onResize);
  };
}

